// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

// ─────────────────────────────────────────────────────────────────────────────
// EtherTrack — GHG Audit Trail Contract
// Network:  Ethereum Sepolia Testnet (chainId 11155111)
//           → Production: Polygon Mainnet (chainId 137) — just redeploy,
//             no contract changes needed.
//
// Design:
//   • Every audit action (EMISSION_LOGGED, VERIFIER_INVITED, LOCK, COMMENT…)
//     is written on-chain as an AuditEntry.
//   • Entries are hash-chained: each entry stores the previous entry's hash,
//     creating an immutable linked list. Tampering breaks the chain.
//   • A server-side relayer wallet submits transactions on behalf of companies.
//     Companies never need MetaMask or gas — EtherTrack pays gas.
//   • Entries are grouped by (companyId, year) so each company/year has its
//     own sub-chain.
//   • The contract owner (relayer) is the only address that can write entries.
//     Read access is public — anyone can verify.
//
// Deployment:
//   npx hardhat run scripts/deploy.js --network sepolia
//   → saves address to .env as AUDIT_CONTRACT_ADDRESS
// ─────────────────────────────────────────────────────────────────────────────

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

contract AuditTrail is Ownable, Pausable {

    // ── Action types — mirrors ACTION_COLORS in AuditTrail.jsx ───────────────
    // Stored as uint8 to save gas vs string
    uint8 public constant ACTION_CREATE  = 1;
    uint8 public constant ACTION_UPDATE  = 2;
    uint8 public constant ACTION_DELETE  = 3;
    uint8 public constant ACTION_VERIFY  = 4;
    uint8 public constant ACTION_SIGN    = 5;
    uint8 public constant ACTION_LOCK    = 6;
    uint8 public constant ACTION_IMPORT  = 7;
    uint8 public constant ACTION_COMMENT = 8;

    // ── Structs ───────────────────────────────────────────────────────────────
    struct AuditEntry {
        uint256 id;           // Sequential ID within (companyId, year)
        string  companyId;    // EtherTrack company/user ID (UUID string)
        uint16  year;         // Reporting year e.g. 2025
        uint8   action;       // ACTION_* constant above
        string  message;      // Human-readable audit message
        string  metaJson;     // JSON string of metadata (user, factor, etc.)
        bytes32 entryHash;    // SHA-256 of (companyId+year+action+message+meta+ts+prevHash)
        bytes32 prevHash;     // Hash of previous entry in this (companyId, year) chain
        uint256 timestamp;    // block.timestamp when logged
        address relayer;      // Relayer wallet that submitted this tx
    }

    // ── Storage ───────────────────────────────────────────────────────────────
    // companyId => year => AuditEntry[]
    mapping(string => mapping(uint16 => AuditEntry[])) private _entries;

    // companyId => year => last hash (for chain linking)
    mapping(string => mapping(uint16 => bytes32)) private _lastHash;

    // companyId => year => locked
    mapping(string => mapping(uint16 => bool)) private _locked;

    // companyId => year => entry count (for quick stats)
    mapping(string => mapping(uint16 => uint256)) public entryCounts;

    // Global entry count
    uint256 public totalEntries;

    // ── Events ────────────────────────────────────────────────────────────────
    event EntryLogged(
        string  indexed companyId,
        uint16  indexed year,
        uint256         entryId,
        uint8           action,
        bytes32         entryHash,
        bytes32         prevHash,
        uint256         timestamp
    );

    event InventoryLocked(
        string  indexed companyId,
        uint16  indexed year,
        address         lockedBy,
        uint256         timestamp
    );

    // ── Modifiers ─────────────────────────────────────────────────────────────
    modifier notLocked(string calldata companyId, uint16 year) {
        require(!_locked[companyId][year], "Inventory locked for this year");
        _;
    }

    modifier validYear(uint16 year) {
        require(year >= 2000 && year <= 2100, "Invalid year");
        _;
    }

    modifier nonEmptyString(string calldata s) {
        require(bytes(s).length > 0, "String cannot be empty");
        _;
    }

    // ── Constructor ───────────────────────────────────────────────────────────
    // initialOwner = relayer wallet address
    constructor(address initialOwner) Ownable(initialOwner) {}

    // ── Core write — only relayer (owner) can call ────────────────────────────
    /**
     * @notice Log an audit entry on-chain.
     * @param companyId   EtherTrack company UUID
     * @param year        Reporting year
     * @param action      ACTION_* constant
     * @param message     Human-readable message
     * @param metaJson    JSON metadata string
     * @param entryHash   Pre-computed SHA-256 hash (matches server-side hash)
     *
     * NOTE: entryHash is computed server-side (Node crypto) and passed in.
     *       The contract stores it as-is — it does NOT recompute it.
     *       This keeps the hash algorithm consistent with the backend and
     *       avoids expensive on-chain string hashing.
     *       Verifiers can recompute the hash off-chain and compare.
     */
    function logEntry(
        string  calldata companyId,
        uint16           year,
        uint8            action,
        string  calldata message,
        string  calldata metaJson,
        bytes32          entryHash
    )
        external
        onlyOwner
        whenNotPaused
        notLocked(companyId, year)
        validYear(year)
        nonEmptyString(companyId)
        nonEmptyString(message)
        returns (uint256 entryId)
    {
        require(action >= 1 && action <= 8, "Invalid action type");
        require(bytes(message).length <= 2000, "Message too long");
        require(bytes(metaJson).length <= 2000, "Meta too long");

        bytes32 prevHash = _lastHash[companyId][year];
        entryId          = entryCounts[companyId][year];

        AuditEntry memory entry = AuditEntry({
            id:        entryId,
            companyId: companyId,
            year:      year,
            action:    action,
            message:   message,
            metaJson:  metaJson,
            entryHash: entryHash,
            prevHash:  prevHash,
            timestamp: block.timestamp,
            relayer:   msg.sender
        });

        _entries[companyId][year].push(entry);
        _lastHash[companyId][year]    = entryHash;
        entryCounts[companyId][year] += 1;
        totalEntries                 += 1;

        emit EntryLogged(
            companyId, year, entryId,
            action, entryHash, prevHash,
            block.timestamp
        );

        return entryId;
    }

    /**
     * @notice Lock an inventory year — no more entries can be added.
     *         Mirrors the ISO 14064-3 data freeze in the backend.
     */
    function lockInventory(
        string calldata companyId,
        uint16          year
    )
        external
        onlyOwner
        whenNotPaused
        validYear(year)
        nonEmptyString(companyId)
    {
        require(!_locked[companyId][year], "Already locked");
        _locked[companyId][year] = true;

        emit InventoryLocked(companyId, year, msg.sender, block.timestamp);
    }

    // ── Read functions — public, no gas cost ──────────────────────────────────

    function getEntry(
        string calldata companyId,
        uint16          year,
        uint256         entryId
    ) external view returns (AuditEntry memory) {
        require(entryId < entryCounts[companyId][year], "Entry not found");
        return _entries[companyId][year][entryId];
    }

    function getAllEntries(
        string calldata companyId,
        uint16          year
    ) external view returns (AuditEntry[] memory) {
        return _entries[companyId][year];
    }

    function getLastHash(
        string calldata companyId,
        uint16          year
    ) external view returns (bytes32) {
        return _lastHash[companyId][year];
    }

    function isLocked(
        string calldata companyId,
        uint16          year
    ) external view returns (bool) {
        return _locked[companyId][year];
    }

    function getEntryCount(
        string calldata companyId,
        uint16          year
    ) external view returns (uint256) {
        return entryCounts[companyId][year];
    }

    /**
     * @notice Verify the hash chain integrity for a (companyId, year).
     *         Returns (intact, brokenAt) where brokenAt = max uint256 if intact.
     *         Anyone can call this — no trust required.
     */
    function verifyChain(
        string calldata companyId,
        uint16          year
    ) external view returns (bool intact, uint256 brokenAt) {
        AuditEntry[] storage chain = _entries[companyId][year];
        uint256 len = chain.length;

        if (len == 0) return (true, type(uint256).max);

        for (uint256 i = 1; i < len; i++) {
            if (chain[i].prevHash != chain[i - 1].entryHash) {
                return (false, i);
            }
        }
        return (true, type(uint256).max);
    }

    // ── Admin ─────────────────────────────────────────────────────────────────
    function pause()   external onlyOwner { _pause(); }
    function unpause() external onlyOwner { _unpause(); }
}

